async function api(path,init={},auth=true){if(webRequestTarget({demoSession:state.demo,demoMode:config.demoMode,apiBaseUrl:config.apiBaseUrl,auth})==='demo'){const data=await webDemo.request(path,init);return !state.demo&&(init.method||'GET')==='GET'&&/^\/v1\/projects\/[^/?]+$/.test(path)?publicProjectView(data):data;}if(!config.apiBaseUrl){if(auth)throw Object.assign(new Error('Sign in is required.'),{status:401});throw new Error('Web API base URL is not configured.')}const headers=new Headers(init.headers||{});headers.set('Accept','application/json');if(init.body&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');if(auth){if(!state.token)throw Object.assign(new Error('Sign in is required.'),{status:401});headers.set('Authorization',`Bearer ${state.token}`)}const response=await fetch(`${config.apiBaseUrl}${path}`,{...init,headers});const text=await response.text();let body=null;try{body=text?JSON.parse(text):null}catch{body=text}if(!response.ok)throw Object.assign(new Error(body?.error||`Request failed (${response.status})`),{status:response.status,body});return body}
